import operator
import re
from typing import Any

import nh3
from django import template
from django.db.models import Sum
from django.template.defaultfilters import linebreaks
from django.utils.html import escape
from django.utils.safestring import mark_safe

register = template.Library()

SPORT_ICON_MAP: dict[str, str] = {
    "SOCCER": "mdi mdi-soccer",
    "BASKETBALL": "mdi mdi-basketball",
    "BASEBALL": "mdi mdi-baseball",
    "HOCKEY": "mdi mdi-hockey-puck",
    "ROWING": "mdi mdi-rowing",
    "BALLET": "mdi mdi-human-female-dance",
}
DEFAULT_SPORT_ICON = "mdi mdi-trophy"
EVENT_DESCRIPTION_ALLOWED_TAGS = {
    "a",
    "br",
    "em",
    "li",
    "ol",
    "p",
    "strong",
    "ul",
}
EVENT_DESCRIPTION_ALLOWED_ATTRIBUTES = {"a": {"href", "title"}}
EVENT_DESCRIPTION_ALLOWED_URL_SCHEMES = {"http", "https", "mailto"}
HTML_TAG_RE = re.compile(r"</?[a-zA-Z][^>]*>")


@register.simple_tag
def sport_icon_class(subcategory: str | None) -> str:
    """Return the MDI CSS class for a sports subcategory."""
    if not subcategory:
        return DEFAULT_SPORT_ICON
    return SPORT_ICON_MAP.get(subcategory, DEFAULT_SPORT_ICON)


@register.filter
def event_description_html(description: str | None) -> str:
    if not description:
        return ""

    if not HTML_TAG_RE.search(description):
        return str(linebreaks(description))

    clean_html = nh3.clean(
        description,
        tags=EVENT_DESCRIPTION_ALLOWED_TAGS,
        attributes=EVENT_DESCRIPTION_ALLOWED_ATTRIBUTES,
        url_schemes=EVENT_DESCRIPTION_ALLOWED_URL_SCHEMES,
    )
    # nh3 has parsed and sanitized the imported calendar HTML before Django
    # treats this description as renderable markup.
    # nosemgrep: python.django.security.audit.avoid-mark-safe.avoid-mark-safe
    return mark_safe(clean_html)  # noqa: S308  # nosec


@register.filter
def get_item(dictionary: Any, key: Any) -> Any:
    """
    Gets an item from a dictionary using the key.
    Usage: {{ my_dict|get_item:key_variable }}
    """
    if dictionary is None:
        return None
    return dictionary.get(str(key))


@register.filter
def mul(value: Any, arg: Any) -> Any:
    """
    Multiplies the value by the argument.
    Usage: {{ value|mul:100 }}
    """
    try:
        return float(value) * float(arg)
    except (ValueError, TypeError):
        return 0


@register.filter
def filter_by_family(queryset: Any, family: Any) -> Any:
    """
    Filters a queryset of family memberships by the given family.
    Usage: {{ user.family_memberships.get_queryset|filter_by_family:family }}
    """
    return queryset.filter(family=family)


@register.filter
def get_display(obj: Any, method_name: str) -> Any:
    """
    Gets the display value for a field using the specified get_*_display method.
    Usage: {{ object|get_display:'get_field_display' }}
    """
    if obj and hasattr(obj, method_name):
        method = getattr(obj, method_name)
        if callable(method):
            return method()
    return ""


@register.filter
def map(sequence: Any, attr: Any) -> Any:
    """
    Maps a sequence of objects to a sequence of attributes.
    Usage: {{ my_list|map:'attribute_name' }}
    """
    return [getattr(item, attr) for item in sequence]


@register.filter
def sum(sequence: Any, attr: Any = None) -> Any:
    """
    Sums the attribute values of a sequence of objects.
    Usage: {{ my_list|sum:'attribute_name' }}
    If no attribute is provided, sums the items directly.
    """
    if attr:
        try:
            # For QuerySets, use Django's Sum aggregation
            if hasattr(sequence, "aggregate"):
                return sequence.aggregate(Sum(attr))[f"{attr}__sum"] or 0
            # For regular sequences
            return sum(getattr(item, attr, 0) for item in sequence)
        except (TypeError, AttributeError):
            return 0
    else:
        try:
            return sum(sequence)
        except (TypeError, ValueError):
            return 0


@register.filter
def selectattr(sequence: Any, args: Any) -> Any:
    """
    Filters a sequence of objects by comparing an attribute to a value.
    Usage: {{ my_list|selectattr:"attribute,eq,value" }}
    Supports operators: eq (equals), ne (not equals), gt (greater than), lt (less than)
    """
    if not sequence:
        return []

    try:
        # Parse arguments
        parts = args.split(",", 2)
        if len(parts) != 3:
            return []

        attr, op_name, value = parts

        # Define operators
        ops = {
            "eq": operator.eq,
            "ne": operator.ne,
            "gt": operator.gt,
            "lt": operator.lt,
            "ge": operator.ge,
            "le": operator.le,
        }

        if op_name not in ops:
            return []

        op_func = ops[op_name]

        # Filter the sequence
        return [item for item in sequence if op_func(getattr(item, attr, None), value)]  # type: ignore[arg-type]
    except (AttributeError, ValueError, TypeError):
        return []


@register.filter
def add_class(field: Any, css_class: Any) -> Any:
    """
    Add a CSS class to a form field
    Usage: {{ form.field|add_class:"form-control" }}
    """
    return field.as_widget(attrs={"class": css_class})


@register.filter
def highlight_regex(text: str, pattern: str) -> Any:
    """
    Highlight parts of text that match the given regex pattern
    """
    if not pattern:
        return text

    try:
        escaped_text = escape(text)
        regex = re.compile(pattern, re.IGNORECASE)

        def replace_match(match: Any) -> str:
            matched_text = match.group(0)
            return f'<span class="matched-text">{matched_text}</span>'

        highlighted = regex.sub(replace_match, escaped_text)
        # matched_text comes from escaped_text, so the inserted span is the only HTML.
        return mark_safe(highlighted)  # noqa: S308  # nosec
    except re.error:
        # If regex is invalid, return the original text
        return text

